/bin/bash -lc "cat >> src/styles.css <<'EOF'

/* On wide screens, a quiet description column keeps every setting in view. */
.sidebar{overflow-y:auto}
@media(min-width:1000px){
  main{max-width:1100px;padding-top:34px}
  .page-heading{margin-bottom:26px}
  h1{font-size:30px}
  .settings-section{display:grid;grid-template-columns:205px minmax(0,1fr);gap:0 25px;padding:25px 29px}
  .section-heading{align-items:flex-start;margin-bottom:0;gap:11px}
  .section-heading h2{font-size:13px}
  .section-heading p{font-size:10px;line-height:1.8;max-width:155px;margin-top:5px}
  .personal-section .section-heading{grid-row:span 2}
  .personal-section .field-grid,.personal-section .avatar-row{grid-column:2}
  .avatar-row{margin-bottom:23px}
  .large-avatar{width:65px;height:65px}
  .field label{font-size:11px}
  .field input,.field select{font-size:12px;height:39px}
  .input-with-icon>svg,.select-start-icon,.select-wrap>svg:last-child{top:11px}
  .language-flag{top:9px}
  .field-hint{font-size:9px}
  .security-option{align-self:center}
  .security-option p{font-size:10px;line-height:1.8;max-width:350px}
  .option-title label{font-size:12px}
  .notifications-section .section-heading{margin-bottom:0}
  .notifications-section .email-chip{display:none}
  .checkbox-title{font-size:12px}
  .checkbox-hint{font-size:10px;margin-top:3px}
  .notification-options{gap:16px}
  .form-footer{padding:20px 29px}
  .privacy-note{font-size:10px;max-width:none}
  .button{font-size:12px;height:37px}
  .upload-button{font-size:10px;height:32px}
  .page-footer{padding-top:21px;padding-bottom:22px}
}
EOF"

/bin/bash -lc "cat > /tmp/orbit-ui-check.cjs <<'NODE'
const {chromium}=require('/home/sandbox/workspace/node_modules/playwright');
const assert=require('node:assert/strict');
(async()=>{
  const browser=await chromium.launch({executablePath:chromium.executablePath(),headless:true,args:['--no-sandbox']});
  const page=await browser.newPage({viewport:{width:1440,height:1000},deviceScaleFactor:1});
  const errors=[];page.on('pageerror',e=>errors.push(e.message));page.on('dialog',dialog=>dialog.accept());
  await page.goto('http://localhost:5181');await page.evaluate(()=>document.fonts.ready);
  await page.screenshot({path:'/tmp/orbit-desktop.png',fullPage:true});
  console.log('Layout',await page.evaluate(()=>({height:document.body.scrollHeight,font:getComputedStyle(document.querySelector('h1')).fontFamily,background:getComputedStyle(document.querySelector('.g-root')).backgroundColor,saveBottom:document.querySelector('.form-footer').getBoundingClientRect().bottom})));
  const save=()=>page.locator('button[type=submit]').click();
  const cancel=()=>page.locator('.cancel-button').click();
  await page.locator('#name').fill('');await page.locator('#email').fill('invalid');await save();
  assert.equal(await page.locator('#name').getAttribute('aria-invalid'),'true');assert.equal(await page.locator('#email').getAttribute('aria-invalid'),'true');assert.equal(await page.locator('#name').evaluate(e=>document.activeElement===e),true);
  await cancel();assert.equal(await page.locator('#name').inputValue(),'Александр Петров');
  console.log('PASS validation and cancellation');
  await page.locator('#name').fill('Мария Иванова');await page.locator('#email').fill('maria@example.com');await page.locator('#language').selectOption('en');
  assert.equal(await page.locator('h1').innerText(),'Profile settings');
  await page.locator('#timezone').selectOption('Asia/Tokyo');await page.getByRole('switch').click();await page.getByRole('checkbox',{name:'Weekly digest',exact:false}).check();await save();
  await page.reload();assert.equal(await page.locator('#name').inputValue(),'Мария Иванова');assert.equal(await page.locator('#email').inputValue(),'maria@example.com');assert.equal(await page.locator('#timezone').inputValue(),'Asia/Tokyo');assert.equal(await page.getByRole('switch').getAttribute('aria-checked'),'true');assert.equal(await page.getByRole('checkbox',{name:'Weekly digest',exact:false}).isChecked(),true);
  console.log('PASS persistence, localization, time zone, toggle and notification preferences');
  await page.locator('#language').selectOption('ru');await page.locator('#name').fill('Черновик');await cancel();assert.equal(await page.locator('h1').innerText(),'Profile settings');assert.equal(await page.locator('#name').inputValue(),'Мария Иванова');
  await page.locator('input[type=file]').setInputFiles('/home/sandbox/workspace/public/avatar.jpg');
  await page.waitForFunction(()=>document.querySelector('.large-avatar img')?.getAttribute('src').startsWith('data:image/webp'));
  await save();await page.reload();assert.ok((await page.locator('.large-avatar img').getAttribute('src')).startsWith('data:image/webp'));
  await page.getByRole('button',{name:'Remove',exact:true}).click();assert.equal(await page.locator('.large-avatar img').count(),0);await cancel();assert.equal(await page.locator('.large-avatar img').count(),1);
  await page.locator('input[type=file]').setInputFiles({name:'invalid.txt',mimeType:'text/plain',buffer:Buffer.from('invalid image')});assert.ok((await page.locator('#avatar-hint').innerText()).includes('Choose a JPG'));await cancel();
  await page.locator('input[type=file]').setInputFiles({name:'large.jpg',mimeType:'image/jpeg',buffer:Buffer.alloc(5*1024*1024+1)});assert.ok((await page.locator('#avatar-hint').innerText()).includes('Choose a JPG'));await cancel();
  console.log('PASS avatar upload, compression, persistence, removal, cancellation and file validation');
  await page.getByRole('button',{name:'Need help?',exact:true}).click();assert.equal(await page.locator('dialog').evaluate(e=>e.open),true);await page.keyboard.press('Escape');assert.equal(await page.locator('dialog').evaluate(e=>e.open),false);
  await page.evaluate(()=>localStorage.clear());await page.reload();
  for(const width of [360,390,768,1024,1440]){await page.setViewportSize({width,height:900});assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=window.innerWidth),"'`overflow at ${width}`)}
  await page.setViewportSize({width:390,height:844});await page.screenshot({path:'"'/tmp/orbit-mobile.png',fullPage:true});
  await page.locator('.mobile-menu').click();assert.equal(await page.locator('.sidebar').evaluate(e=>e.classList.contains('is-open')),true);
  await page.locator('.side-nav').getByRole('button',{name:'Безопасность',exact:true}).click();assert.equal(await page.locator('.sidebar').evaluate(e=>e.classList.contains('is-open')),false);
  assert.equal(errors.length,0,JSON.stringify(errors));console.log('PASS help modal, mobile navigation, five responsive widths and no browser errors');
  await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
NODE"
